const REAC = { war: ['Não aceitaremos provocações.', 'A paz acabou. Que a história nos julgue.', 'Nossas tropas já estão na fronteira.'], dead: ['Um capítulo da história se fecha.', 'O mapa ficou mais pobre hoje.', 'Descanse em paz.'], indep: ['Hoje somos livres!', 'Nasce uma nova bandeira.', 'O povo decidiu o próprio destino.'], back: ['Voltamos, e para ficar.', 'Nossa bandeira tremula de novo.'], cup: ['É CAMPEÃO!', 'O mundo é nosso, pelo menos no futebol.', 'Feriado nacional decretado.'], elec: ['Obrigado pela confiança!', 'A democracia venceu.', 'Agora é trabalhar.'], gov: ['Tempos novos chegaram.', 'Mudança de rumo.'], cat: ['Toda a nossa solidariedade às vítimas.', 'Vamos reconstruir.'], nuke: ['O mundo nunca mais será o mesmo.', 'Inaceitável.'], peace: ['A paz foi assinada.', 'Chega de guerra.'], unif: ['Juntos somos mais fortes.'], spy: ['Isso é um escândalo diplomático.', 'Exigimos explicações.'] };
