    const rv = P.rival[e.k]; if (rv && live.length > 2 && h % 3) { let a = e.k !== 'war' && B ? B : live[(h >>> 5) % live.length]; if (a === k || a === B && e.k === 'war') a = live[(h >>> 9) % live.length]; if (a !== k) out.push({ t: e.t, k: a, x: fill(rv[(h >>> 2) % rv.length], A, Bn, e.t), h: h + 1 }); }
    const ev = NW && NW.ev[e.k]; if (ev && k && h % 4 !== 3) { const ci = newsPick(NW, h >>> 13, NEWS_BY[e.k]); out.push({ t: e.t, news: ci, x: newsLine(NW, ci, fill(ev[(h >>> 5) % ev.length], A, Bn, e.t, k && k.leader.n), h >>> 1), m: e.m, h: h + 4 }); }
